/* =====================================================
    1. RESET & GLOBALS
===================================================== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}


:root {
    --inventory-accent: #94a3b8;
    --inventory-accent-strong: #475569;
    --inventory-accent-soft: rgba(148, 163, 184, 0.14);
    --inventory-accent-glow: rgba(148, 163, 184, 0.18);
    --inventory-accent-border: rgba(148, 163, 184, 0.32);
    --inventory-accent-text: #e2e8f0;
    --inventory-hero-start: rgba(15, 23, 42, 0.98);
    --inventory-hero-end: rgba(51, 65, 85, 0.94);
}

/* =====================================================
   QUICKSTOCK JA 2026 - INVENTORY WORKBENCH REFINEMENTS
===================================================== */

body.page-transfer-stock .transfer-shell,
body.page-add-item .item-workbench-shell,
body.page-inventory-update .item-workbench-shell {
    max-width: 1480px;
    margin: 0 auto;
    padding: 28px 24px 48px;
}

body.page-transfer-stock .transfer-hero,
body.page-add-item .item-hero-banner,
body.page-inventory-update .item-hero-banner {
    display: grid;
    gap: 18px;
    margin-bottom: 24px;
    border-radius: 28px;
    padding: 28px;
    overflow: hidden;
    position: relative;
    background:
        radial-gradient(circle at top right, var(--inventory-accent-glow), transparent 30%),
        linear-gradient(135deg, var(--inventory-hero-start), var(--inventory-hero-end));
    color: #fff;
    box-shadow: 0 26px 70px rgba(15, 23, 42, 0.2);
}

body.page-add-item .item-hero-banner,
body.page-inventory-update .item-hero-banner {
    grid-template-columns: minmax(0, 1.4fr) minmax(260px, 0.9fr);
    align-items: end;
}

body.page-transfer-stock .transfer-hero {
    grid-template-columns: minmax(0, 1.35fr) minmax(320px, 1fr);
    align-items: stretch;
}

body.page-transfer-stock .transfer-kicker,
body.page-add-item .item-hero-kicker,
body.page-inventory-update .item-hero-kicker,
body.page-add-item .item-rail-eyebrow,
body.page-inventory-update .item-rail-eyebrow,
body.page-transfer-stock .transfer-panel-eyebrow {
    margin: 0 0 10px;
    color: rgba(226, 232, 240, 0.92);
    font-size: 0.74rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.18em;
}

body.page-transfer-stock .transfer-panel-eyebrow {
    color: var(--inventory-accent-strong);
}

body.page-transfer-stock .transfer-hero h1,
body.page-add-item .item-hero-copy h1,
body.page-inventory-update .item-hero-copy h1 {
    margin: 0;
