/* POS payment channels: POS, Tap2Pay, Scan2Pay, WiPay2Me, Invoice. */
body.page-cash-register .payment-channel-panel {
    background: linear-gradient(135deg, #0b72d9 0%, #21a3e7 100%);
    padding: 18px 18px 20px;
    border-top: 1px solid rgba(15, 23, 42, 0.08);
    color: #ffffff;
}

body.page-cash-register .payment-channel-summary {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 12px;
    padding: 16px;
    border-radius: 12px;
    background: #ffffff;
    color: #111827;
    box-shadow: 0 16px 28px rgba(15, 23, 42, 0.18);
}

body.page-cash-register .payment-channel-icon {
    width: 40px;
    height: 40px;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: #0b72d9;
    color: #ffffff;
}

body.page-cash-register .payment-channel-summary strong,
body.page-cash-register .payment-channel-summary span {
    display: block;
}

body.page-cash-register #payment-channel-title {
    font-size: 0.95rem;
    font-weight: 900;
}

body.page-cash-register #payment-channel-subtitle,
body.page-cash-register #payment-channel-method {
    margin-top: 4px;
    color: #64748b;
    font-size: 0.8rem;
}

body.page-cash-register .payment-channel-total {
    text-align: right;
}

body.page-cash-register #payment-channel-total {
    color: #059669;
    font-size: 1.05rem;
}

body.page-cash-register .payment-channel-options {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 10px;
    margin-top: 16px;
}

body.page-cash-register .payment-channel-option {
    position: relative;
    min-height: 68px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border: 2px solid transparent;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.86);
    color: #1e293b;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.12);
}

body.page-cash-register .payment-channel-option.active {
    border-color: #ffffff;
    background: #096fd4;
    color: #ffffff;
    box-shadow: 0 12px 22px rgba(15, 23, 42, 0.22);
}

body.page-cash-register .payment-channel-option-icon {
    font-size: 1.1rem;
    line-height: 1;
}

body.page-cash-register .payment-channel-check {
    position: absolute;
    top: -9px;
    right: -7px;
    width: 22px;
    height: 22px;
    display: none;
    place-items: center;
    border-radius: 999px;
    background: #ffffff;
    color: #16a34a;
    font-size: 0.8rem;
    font-weight: 900;
    box-shadow: 0 4px 10px rgba(15, 23, 42, 0.18);
}

body.page-cash-register .payment-channel-option.active .payment-channel-check {
    display: grid;
}

body.page-cash-register .payment-channel-hint {
    margin: 14px 0 0;
    text-align: center;
    color: rgba(255, 255, 255, 0.84);
    font-size: 0.85rem;
}

@media (max-width: 760px) {
    body.page-cash-register .payment-channel-panel {
        padding: 14px 14px 16px;
    }

    body.page-cash-register .payment-channel-options {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
        margin-top: 12px;
    }

    body.page-cash-register .payment-channel-summary {
        grid-template-columns: auto 1fr;
        gap: 10px;
        padding: 12px;
    }

    body.page-cash-register .payment-channel-icon {
        width: 34px;
        height: 34px;
        border-radius: 10px;
    }

    body.page-cash-register #payment-channel-title {
        font-size: 0.88rem;
    }

    body.page-cash-register #payment-channel-subtitle,
    body.page-cash-register #payment-channel-method {
        font-size: 0.74rem;
    }

    body.page-cash-register #payment-channel-total {
        font-size: 0.96rem;
    }

    body.page-cash-register .payment-channel-total {
        grid-column: 1 / -1;
        text-align: left;
        padding-top: 6px;
        border-top: 1px solid #e2e8f0;
    }

    body.page-cash-register .payment-channel-option {
        min-height: 60px;
        gap: 4px;
        border-radius: 10px;
        font-size: 0.72rem;
    }

    body.page-cash-register .payment-channel-option-icon {
        font-size: 0.95rem;
    }

    body.page-cash-register .payment-channel-hint {
        margin-top: 10px;
        font-size: 0.78rem;
    }
}

