            .hero-section h2 { font-size: 3.5rem; font-weight: 800; color: #1a1d21; line-height: 1.1; letter-spacing: -0.05em; }
            
            /* Pricing Grid Layout - Centered for 2 cards */
            .pricing-grid { 
                display: flex; 
                gap: 30px; 
                justify-content: center; 
                margin: 50px 0; 
                flex-wrap: wrap; 
                align-items: stretch;
            }
            
            .pricing-card { 
                background: white; border: 1px solid #e1e4e8; border-radius: 24px; padding: 45px 30px; 
                width: 360px; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s ease;
                display: flex; flex-direction: column; text-align: center; box-shadow: 0 4px 6px rgba(0,0,0,0.02);
                position: relative;
            }
            
            .pricing-card:hover { transform: translateY(-12px); box-shadow: 0 20px 40px rgba(0,0,0,0.08); }
            
            /* Pro Card Styling */
            .pricing-card.pro { border: 2px solid #007bff; z-index: 1; }
            .pro-badge { position: absolute; top: -16px; left: 50%; transform: translateX(-50%); background: #007bff; color: white; padding: 6px 20px; border-radius: 20px; font-size: 0.75rem; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; }
            
            .pricing-card h4 { font-size: 1.5rem; margin-bottom: 10px; color: #212529; }
            .pricing-card ul { list-style: none; padding: 0; margin: 25px 0; text-align: left; flex-grow: 1; }
            .pricing-card li { margin-bottom: 14px; font-size: 0.95rem; color: #4a5568; display: flex; align-items: center; }
            .pricing-card li::before { content: "✓"; color: #059669; font-weight: bold; margin-right: 10px; }
            .pricing-card li.excluded { color: #e53e3e; opacity: 0.6; }
            .pricing-card li.excluded::before { content: "✕"; color: #e53e3e; }
            
            .price { font-size: 2.75rem; font-weight: 800; margin: 20px 0; color: #1a1d21; }
            .price span { font-size: 1rem; color: #718096; font-weight: 400; }
            
            .btn-upgrade { display: block; background: #007bff; color: white; padding: 16px; border-radius: 12px; text-decoration: none; font-weight: 700; transition: all 0.2s; border: none; cursor: pointer; }
            .btn-upgrade:hover { opacity: 0.9; transform: scale(1.02); }
            
            .btn-starter { background: #f1f5f9; color: #1e293b; }

            /* Status Box */
            .current-plan-box { margin-top: 30px; background: #fff; padding: 18px 35px; border-radius: 50px; display: inline-flex; align-items: center; border: 1px solid #e1e4e8; color: #2d3748; font-size: 0.95rem; box-shadow: 0 4px 10px rgba(0,0,0,0.03); }

            /* Feature Sections */
            .section { margin: 90px auto 0; max-width: 1200px; padding: 0 20px; text-align: left; }
            .section-title { font-size: 2rem; font-weight: 800; color: #1a1d21; margin-bottom: 10px; }
            .section-subtitle { color: #64748b; margin-bottom: 30px; font-size: 1.05rem; }
            .pill { display: inline-block; padding: 6px 14px; border-radius: 999px; background: #eef2ff; color: #1d4ed8; font-size: 0.8rem; font-weight: 700; margin-bottom: 12px; }

            .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
            .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

            .card { background: #ffffff; border: 1px solid #e5e7eb; border-radius: 20px; padding: 24px; box-shadow: 0 6px 14px rgba(0,0,0,0.04); }
            .card h4 { margin: 0 0 8px; font-size: 1.15rem; }
            .muted { color: #64748b; }

            /* Demo */
            .demo-wrap { display: grid; grid-template-columns: 1.3fr 1fr; gap: 24px; align-items: center; }
            .demo-frame { background: linear-gradient(135deg, #0f172a 0%, #111827 100%); border-radius: 24px; padding: 18px; color: #e2e8f0; position: relative; min-height: 260px; }
            .demo-frame-link { display: block; text-decoration: none; cursor: pointer; transition: transform 0.2s ease, box-shadow 0.2s ease; }
            .demo-frame-link:hover { transform: translateY(-2px); box-shadow: 0 18px 36px rgba(15, 23, 42, 0.18); }
            .demo-frame-link:focus-visible { outline: 3px solid rgba(37, 99, 235, 0.45); outline-offset: 4px; }
            .demo-screen { background: #0b1220; border: 1px solid rgba(255,255,255,0.1); border-radius: 18px; height: 220px; display: flex; align-items: center; justify-content: center; }
            .play-btn { width: 64px; height: 64px; border-radius: 50%; background: #2563eb; display: grid; place-items: center; box-shadow: 0 10px 30px rgba(37,99,235,0.4); }
            .play-btn::before { content: ""; display: block; width: 0; height: 0; border-left: 16px solid #fff; border-top: 10px solid transparent; border-bottom: 10px solid transparent; margin-left: 4px; }

            /* Comparison */
            .compare-table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e5e7eb; border-radius: 20px; overflow: hidden; }
            .compare-table th, .compare-table td { padding: 16px; border-bottom: 1px solid #f1f5f9; text-align: left; }
            .compare-table th { background: #f8fafc; font-weight: 800; }
            .compare-yes { color: #059669; font-weight: 700; }
            .compare-no { color: #e53e3e; font-weight: 700; }

            /* FAQ */
            .faq details { background: #fff; border: 1px solid #e5e7eb; border-radius: 14px; padding: 14px 18px; margin-bottom: 12px; }
            .faq summary { cursor: pointer; font-weight: 700; list-style: none; }
            .faq summary::-webkit-details-marker { display: none; }
            .faq summary::after { content: "+"; float: right; color: #2563eb; }
            .faq details[open] summary::after { content: "–"; }
            .faq p { margin: 10px 0 0; color: #475569; }

            /* Integrations */
            .logo-row { display: flex; gap: 12px; flex-wrap: wrap; }
            .logo-pill { border: 1px dashed #cbd5e1; padding: 10px 14px; border-radius: 999px; background: #f8fafc; font-weight: 700; color: #334155; }

            /* Security */
            .security-list { list-style: none; padding: 0; margin: 0; }
            .security-list li { padding: 10px 0; border-bottom: 1px solid #f1f5f9; display: flex; gap: 10px; }
            .security-list li::before { content: "🔒"; }

            /* CTA */
            .cta { background: linear-gradient(135deg, #0ea5e9 0%, #2563eb 100%); color: #fff; border-radius: 26px; padding: 30px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
            .cta h3 { margin: 0 0 6px; font-size: 1.6rem; }
