            .cta .btn { background: #fff; color: #1e293b; padding: 12px 18px; border-radius: 12px; text-decoration: none; font-weight: 800; }

            @media (max-width: 1100px) { .pricing-grid { flex-direction: column; align-items: center; } .pricing-card { width: 100%; max-width: 400px; } }
            @media (max-width: 1000px) { .grid-3 { grid-template-columns: 1fr; } .grid-2 { grid-template-columns: 1fr; } .demo-wrap { grid-template-columns: 1fr; } .cta { flex-direction: column; align-items: flex-start; } }

