/* =====================================================
   PAGE: DASHBOARD COMMAND CENTER
   Theme: Dashboard Midnight / Professional Slate
===================================================== */

:root {
    /* Core Palette */
    --primary-blue: #3b82f6;
    --dark-bg: #0f172a;
    --dark-surface: #1e293b;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --warning-orange: #f59e0b;
    
    /* Text & UI */
    --text-main: #1e293b;
    --text-muted: #64748b;
    --bg-canvas: #f8fafc;
    --border-light: #e2e8f0;
    --white: #ffffff;
    
    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

/* 1. Global Reset & Body */
* { margin: 0; padding: 0; box-sizing: border-box; }

body.page-dashboard {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg-canvas);
    color: var(--text-main);
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}


/* 2. Header: Professional Command Bar */
header {
    background: var(--dark-bg);
    color: var(--white);
    padding: 12px 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-blue);
    position: sticky;   
    top: 0;
    z-index: 1000;
}

.logo-area {
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none;
    color: var(--white);
}

.logo-img {
    height: 32px;
    border-radius: 6px;
}

.status-pill {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid var(--success-green);
    color: var(--success-green);
    padding: 6px 12px;
    border-radius: 50px;
    font-size: 0.75rem;
    font-weight: 800;
    text-decoration: none;
    transition: all 0.2s;
    
}

.status-pill:hover { background: var(--success-green); color: white; }

/* Add this to your #main-nav rule */
#main-nav {
    position: sticky;
    top: 70px;
    display: flex;
    justify-content: center;
    align-items: center; /* Ensures vertical alignment */
    /* ... keep your existing properties ... */
}

/* New CSS for the search icon */
.nav-search-trigger {
    position: absolute;
    right: 25px; /* Adjust based on your side padding */
    display: flex;
    align-items: center;
    color: var(--text-muted);
    transition: color 0.2s ease;
    border-bottom: none !important; /* Prevents the blue underline on the icon */
    padding: 0 !important; 
}

.nav-search-trigger:hover {
    color: var(--primary-blue);
}

/* Mobile check: If the screen is too small, let it scroll naturally */
@media (max-width: 850px) {
    .nav-search-trigger {
        position: static; /* Re-enters the flow so it doesn't overlap text */
        margin-left: 15px;
    }
    #main-nav {
        justify-content: flex-start; /* Better for horizontal scrolling on mobile */
    }
}


/* 4. Layout Container */
main {
    flex: 1;
    padding: 25px 30px;
    max-width: 1400px;
    width: 100%;
    margin: 0 auto;
    /* 4. MAIN CONTENT SPACING */

    margin-top: 0 !important;
    padding-top: 25px; /* This is where the "breathing room" should come from */

}

/* 5. Welcome & Filters */
.welcome-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 25px;
    flex-wrap: wrap;
    gap: 15px;
}

.welcome-header h2 { font-weight: 800; font-size: 1.75rem; color: var(--dark-bg); letter-spacing: -0.5px; }

.filter-form {
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--white);
    padding: 8px 15px;
    border-radius: 10px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-sm);
}

.filter-form select {
    padding: 6px;
    border: 1px solid var(--border-light);
    border-radius: 6px;
    font-weight: 600;
}

.btn-apply {
    background: var(--dark-bg);
    color: white;
    border: none;
    padding: 8px 16px;
    border-radius: 6px;
    font-weight: 700;
    cursor: pointer;
}

/* 6. KPI Grid & Cards */
.kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 18px;
}

.kpi-card {
    background: var(--white);
    padding: 24px;
    border-radius: 14px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s;
}

.kpi-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }

.kpi-label {
    display: block;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 8px;
}

.kpi-value {
    font-size: 2rem;
    font-weight: 800;
    color: var(--dark-bg);
    font-family: 'JetBrains Mono', monospace;
    margin-bottom: 10px;
}

/* 7. Badges & Progress */
.badge {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: 800;
}

.badge-success { background: #dcfce7; color: #166534; }

.progress-track {
    background: #e2e8f0;
    height: 8px;
    border-radius: 10px;
    margin-top: 15px;
    overflow: hidden;
}

.progress-fill {
    height: 100%;
    background: var(--primary-blue);
    border-radius: 10px;
    transition: width 1s ease-in-out;
}

/* 8. Mini Tables (Inside KPI Cards) */
.mini-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
}

.mini-table td {
    padding: 8px 0;
    border-bottom: 1px solid #f1f5f9;
}

