/* =====================================================
   PAGE: ADVANCED ANALYTICS
   Midnight High-Contrast / Data-Focus
===================================================== */

:root {
    /* Functional Palette */
    --primary-blue: #3b82f6;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --dark-bg: #0f172a;
    
    /* Light Mode (Default) */
    --surface: #ffffff;
    --surface-muted: #f8fafc;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --bg-canvas: #f1f5f9;
    --card-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

/* Dark Mode Overrides */
[data-theme="dark"], .force-dark {
    --surface: #1e293b;
    --surface-muted: #0f172a;
    --text-main: #f1f5f9;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --bg-canvas: #0f172a;
}

/* 1. Base Styles */
body {
    background-color: var(--bg-canvas);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    margin: 0;
    transition: background 0.3s ease, color 0.3s ease;
}

main {
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px;
}

/* 2. Header & Navigation Sync */
header {
    background: var(--dark-bg);
    padding: 12px 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-blue);
    top: 0;
    z-index: 1000;
}


/* 3. Report Cards */
.report-card {
    background: var(--surface);
    padding: 24px;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    box-shadow: var(--card-shadow);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.report-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

/* 4. Layout Grids */
.report-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 25px;
}

/* 5. Buttons & Controls */
.btn-filter {
    padding: 6px 14px;
    border-radius: 8px;
    font-size: 0.75rem;
    font-weight: 700;
    text-decoration: none;
    border: 1px solid var(--border-color);
    transition: all 0.2s;
}

.btn-filter:hover {
    border-color: var(--primary-blue);
}

.btn-export {
    display: block;
    text-align: center;
    padding: 12px;
    border-radius: 10px;
    color: white;
    text-decoration: none;
    font-weight: 700;
    font-size: 0.85rem;
    transition: filter 0.2s, transform 0.1s;
}

.btn-export:hover {
    filter: brightness(1.1);
    transform: translateY(-1px);
}

/* 6. Charts & Tables */
.chart-container {
    position: relative;
    height: 300px;
    width: 100%;
}

table th {
    border-bottom: 2px solid var(--border-color);
    padding: 10px;
}

table td {
    padding: 12px 10px;
    border-bottom: 1px solid var(--surface-muted);
}

/* 7. Restock Priority Styling */
.restock-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.restock-item {
    background: var(--surface-muted);
    padding: 12px;
    border-radius: 10px;
    border: 1px solid var(--border-color);
}

/* 8. Ledger Pulse Section */
.ledger-section {
    position: relative;
    overflow: hidden;
}

.ledger-section::after {
    content: "ANALYSIS_ACTIVE";
    position: absolute;
    top: 15px;
    right: 15px;
    font-size: 0.5rem;
    font-weight: 900;
    color: var(--primary-blue);
    opacity: 0.3;
    letter-spacing: 2px;
}


