        border: 1px solid var(--pos-border);
        padding: 5px 12px;
        border-radius: 6px;
        font-size: 0.65rem;
        font-weight: 800;
        text-transform: uppercase;
        cursor: pointer;
        transition: 0.2s;
    }

    .breakdown-master button:hover {
        background: var(--pos-dark);
        color: white;
    }

    .breakdown-toggle {
        background: transparent;
        border: 1px solid var(--primary-blue);
        color: var(--primary-blue);
        font-size: 0.6rem;
        font-weight: 800;
        padding: 4px 8px;
        border-radius: 4px;
        cursor: pointer;
        text-transform: uppercase;
    }

    .stock-breakdown {
        background: var(--surface-muted);
        border: 1px dashed var(--pos-border);
        border-radius: 8px;
        padding: 12px;
        margin-top: 10px;
        text-align: left;
        font-size: 0.75rem;
    }

    .stock-breakdown ul {
        list-style: none;
        padding: 0;
        margin: 8px 0 0;
    }

    .stock-breakdown li {
        padding: 4px 0;
        border-bottom: 1px solid rgba(0,0,0,0.05);
        display: flex;
        justify-content: space-between;
    }

    /* 3. Stock Health Badges */
    .badge {
        padding: 6px 12px;
        border-radius: 20px;
        font-size: 0.7rem;
        font-weight: 800;
        text-transform: uppercase;
    }

    .in-stock { background: rgba(46, 213, 115, 0.15); color: #27ae60; }
    .low-stock { background: rgba(241, 196, 15, 0.15); color: #f39c12; }
    .out-of-stock { background: rgba(231, 76, 60, 0.15); color: #c0392b; }

    /* 4. Table Polish */
    #inventoryTable {
        width: 100%;
        border-collapse: collapse;
        margin-top: 1rem;
    }

    #inventoryTable th {
        text-align: left;
        padding: 15px;
        font-size: 0.7rem;
        text-transform: uppercase;
        color: var(--text-muted);
        border-bottom: 2px solid var(--pos-border);
    }

    #inventoryTable td {
        padding: 18px 15px;
        border-bottom: 1px solid var(--pos-border);
    }

    .sku-tag {
        font-family: 'JetBrains Mono', monospace;
        background: var(--pos-dark);
        color: white;
        padding: 4px 8px;
        border-radius: 5px;
        font-size: 0.75rem;
    }

    .price-tag {
        font-weight: 800;
        color: var(--text-main);
        font-family: 'JetBrains Mono';
    }

    /* 5. Action Footer */
    .action-footer {
        margin-top: 2rem;
        padding-top: 2rem;
        border-top: 1px solid var(--pos-border);
        display: flex;
        justify-content: space-between;
        align-items: center;
    }

    .btn {
        padding: 12px 24px;
        border-radius: 10px;
        font-weight: 800;
        font-size: 0.8rem;
        text-decoration: none;
        transition: 0.2s;
        cursor: pointer;
        border: none;
    }

    .btn-primary { background: var(--primary-blue); color: white; }
    .btn-outline { background: transparent; border: 2px solid var(--pos-dark); color: var(--pos-dark); }

    .btn:hover { transform: translateY(-2px); box-shadow: 0 5px 15px rgba(0,0,0,0.1); }
    /* 6. Row-Level Actions (Modify & Delete) */
.action-btn-modify {
    background: var(--surface-muted);
    color: var(--pos-dark);
    border: 1px solid var(--pos-border);
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 0.65rem;
    font-weight: 800;
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.action-btn-modify:hover {
    background: var(--primary-blue);
    color: white;
    border-color: var(--primary-blue);
    transform: translateY(-1px);
}

.action-btn-delete {
    background: rgba(239, 68, 68, 0.08); /* Faint red to reduce visual noise */
    color: #ef4444;
    border: 1px solid rgba(239, 68, 68, 0.2);
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 0.65rem;
    font-weight: 800;
    cursor: pointer;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    transition: all 0.2s;
}

.action-btn-delete:hover {
    background: #ef4444;
    color: white;
    transform: translateY(-1px);
}

.actions-cell {
    white-space: nowrap; /* Keeps buttons on one line */
    text-align: right;
}

/* 7. Typography Optimization */
.price-tag {
    font-family: 'JetBrains Mono', monospace !important;
    font-size: 0.95rem;
    letter-spacing: -0.5px;
}


/* =====================================================
   MOBILE RESPONSIVE OVERRIDES
   ===================================================== */

@media screen and (max-width: 768px) {
    /* 1. Container & Card Reset */
    .main-container {
        padding: 0 10px !important;
        margin: 1rem auto !important;
    }

    .inventory-card {
        padding: 1rem !important;
        border-radius: 12px !important;
    }

    /* 2. Header & Search/Filter Fix (The "Too Wide" Culprit) */
    .inventory-header {
        flex-direction: column !important;
        align-items: stretch !important;
        gap: 20px !important;
    }

    .filters {
        display: flex !important;
        flex-direction: column !important;
        width: 100% !important;
        gap: 10px !important;
    }

    /* Force Search input, Selects, and Button to full width */
    .filters input[name="q"], 
    .filters select, 
    .filters .btn {
        width: 100% !important;
        min-width: 100% !important;
        max-width: none !important;
        box-sizing: border-box !important; /* Keeps padding inside 100% width */
        font-size: 1rem !important; /* Prevents iOS auto-zoom */
        padding: 12px !important;
    }

    .breakdown-master {
        display: grid !important;
        grid-template-columns: 1fr 1fr;
        gap: 8px;
    }

    /* 3. Table to Card Transformation */
    #inventoryTable, 
    #inventoryTable thead, 
    #inventoryTable tbody, 
    #inventoryTable tr, 
    #inventoryTable td {
        display: block !important;
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100% !important;
        box-sizing: border-box !important;
    }

    #inventoryTable {
        table-layout: fixed !important;
        border-collapse: collapse !important;
        overflow-x: hidden !important;
    }

    #inventoryTable thead {
        display: none !important; /* Hide headers on mobile */
    }

    #inventoryTable tr {
        margin-bottom: 1.5rem;
        border: 1px solid var(--pos-border) !important;
        border-radius: 12px;
        padding: 15px !important;
        background: var(--surface);
        max-width: 100% !important;
        overflow-x: hidden !important;
    }

    #inventoryTable td {
        padding: 6px 0 !important;
        border: none !important;
        text-align: left !important;
    }

    #inventoryTable td[data-label="Actions"],
    body.page-inventory #inventoryTable td.actions-cell {
        display: inline-block !important;
        width: fit-content !important;
        max-width: 100% !important;
        margin-left: 0 !important;
        margin-right: auto !important;
        padding-right: 0 !important;
    }

    /* Custom Labels for Card Data */
    #inventoryTable td[data-label="Category"] { font-size: 0.65rem; margin-bottom: 4px; }
    #inventoryTable td[data-label="Product"] { 
        font-size: 1.1rem !important; 
        border-bottom: 1px solid var(--surface-muted) !important;
        padding-bottom: 10px !important;
        margin-bottom: 10px;
    }
    
    #inventoryTable td[data-label="Qty"]:before { content: "STOCK: "; font-weight: 800; color: var(--text-muted); font-size: 0.7rem; }
    #inventoryTable td[data-label="Price"]:before { content: "PRICE: "; font-weight: 800; color: var(--text-muted); font-size: 0.7rem; }

    /* 4. Action Buttons Fix */
    .actions-cell div,
    .actions-cell > div,
    body.page-inventory .actions-cell > div,
    body.page-inventory .actions-cell div[style] {
        justify-content: flex-start !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: stretch !important;
        grid-template-columns: none !important;
        gap: 10px !important;
        width: 100% !important;
        margin-top: 10px;
        padding-top: 10px;
        border-top: 1px dashed var(--pos-border);
    }

    .actions-cell form,
    body.page-inventory .actions-cell form {
        display: block !important;
        width: 100% !important;
        margin: 0 !important;
    }

    .action-btn-modify, .action-btn-delete,
    body.page-inventory .action-btn-modify,
    body.page-inventory .action-btn-delete {
        width: 100% !important;
        min-width: 0 !important;
        box-sizing: border-box !important;
        display: flex !important;
        text-align: center !important;
        justify-content: center !important;
        padding: 12px 0 !important;
    }

    /* 5. Footer Fix */
    .action-footer {
        flex-direction: column !important;
        gap: 15px;
        text-align: center;
    }

    .action-footer div {
        width: 100% !important;
        display: flex;
        flex-direction: column;
        gap: 10px;
    }
}



/* =====================================================
   PAGE: TERMINAL CORE
===================================================== */

:root {
    --primary-blue: #0070f3;
    --pos-dark: #0f172a;
    --pos-border: #e2e8f0;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --surface-light: #f8fafc;
    --status-green: #22c55e;
    --operator-red: #ef4444;
}

/* 1. Base Layout */
body.page-add-item {
    background-color: #ffffff;
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    margin: 0;
}

.mono {
    font-family: 'JetBrains Mono', monospace !important;
}

/* 2. Fixed Header Fix */
.pos-header {
    background: #ffffff;
    border-bottom: 1px solid var(--pos-border);
    padding: 0.75rem 2rem;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.header-main {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.brand-group {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.logo-link {
    text-decoration: none;
    font-weight: 900;
    font-size: 1.2rem;
    color: var(--pos-dark);
    letter-spacing: -1px;
}

.logo-link span { color: var(--primary-blue); }

.nav-separator {
    width: 1px;
    height: 24px;
    background: var(--pos-border);
}

.terminal-label {
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--text-muted);
    letter-spacing: 1px;
}

.status-dot {
    height: 8px;
    width: 8px;
    background: var(--status-green);
    border-radius: 50%;
    display: inline-block;
    margin-right: 6px;
    box-shadow: 0 0 8px rgba(34, 197, 94, 0.4);
}

/* 3. User Profile & Meta */
.meta-group {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.node-status { text-align: right; }
.node-status small { display: block; font-size: 0.55rem; font-weight: 900; color: var(--text-muted); }
.node-status span { font-size: 0.7rem; font-weight: 700; }

.profile-container {
    display: flex;
    align-items: center;
    gap: 12px;
    padding-left: 1.5rem;
    border-left: 1px solid var(--pos-border);
}

.user-avatar {
    width: 32px;
    height: 32px;
    background: var(--pos-dark);
    color: white;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    font-size: 0.8rem;
}

.user-rank { font-size: 0.55rem; color: var(--operator-red); font-weight: 800; }

/* 4. Terminal Grid (Sidebar & Content) */
.terminal-grid {
    display: grid;
    grid-template-columns: 320px 1fr;
    gap: 2rem;
    max-width: 1400px;
    margin: 2rem auto;
    padding: 0 2rem;
}

.sidebar {
    background: var(--surface-light);
    border: 1px solid var(--pos-border);
    border-radius: 12px;
    padding: 1.5rem;
}

.sidebar h3 {
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--primary-blue);
    margin-bottom: 1.5rem;
    border-bottom: 1px solid var(--pos-border);
    padding-bottom: 0.5rem;
}

.preview-box { margin-bottom: 1.25rem; }
.preview-label { display: block; font-size: 0.6rem; font-weight: 800; color: var(--text-muted); text-transform: uppercase; }
.preview-val { font-weight: 700; font-size: 0.95rem; margin-top: 4px; }
.preview-val.highlight { color: var(--primary-blue); }

.margin-badge {
    display: inline-block;
    padding: 6px 12px;
    background: #ffffff;
    border: 1px solid var(--pos-border);
    border-radius: 6px;
    color: var(--status-green);
    font-weight: 800;
    font-size: 0.75rem;
    margin-top: 8px;
}

/* 5. Form Styling */
.content {
    background: white;
    border: 1px solid var(--pos-border);
    border-radius: 12px;
    padding: 2rem;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
}

.field.full { grid-column: span 2; }

.field label {
    display: block;
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--text-muted);
    text-transform: uppercase;
    margin-bottom: 6px;
}

.field input, .field select {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid var(--pos-border);
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    transition: all 0.2s ease;
}

.field input:focus {
    outline: none;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 112, 243, 0.1);
}

.sku-input { background: var(--surface-light); color: var(--primary-blue); }

/* 6. Action Buttons */
.form-actions {
    margin-top: 2rem;
    display: flex;
    gap: 1rem;
    border-top: 1px solid var(--pos-border);
    padding-top: 1.5rem;
}

.btn {
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 800;
    font-size: 0.8rem;
    text-transform: uppercase;
    cursor: pointer;
    border: none;
    transition: transform 0.1s;
}

.btn:active { transform: scale(0.98); }

.btn-primary { background: var(--pos-dark); color: white; }
.btn-ghost { background: var(--surface-light); color: var(--text-muted); text-decoration: none; display: flex; align-items: center; }

/* 7. Footer */
footer {
    text-align: center;
    padding: 2rem;
    font-size: 0.7rem;
    color: var(--text-muted);
    border-top: 1px solid var(--pos-border);
}


/* =====================================================
   PAGE: CASH REGISTER
===================================================== */

/* 1. Fluid Container - Removes the 'centered' restricted width */
.main-container {
    width: 100%;
    max-width: 100vw; /* Fills entire viewport width */
    margin: 0;
    padding: 1.5rem;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-height: calc(100vh - 150px);
}

/* 2. Full-Bleed Inventory Card */
.inventory-card {
    background: var(--surface);
    border: 1px solid var(--pos-border);
    border-radius: 12px;
    padding: 1.5rem;
    flex: 1; /* Allows card to grow with the viewport height */
    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

/* 3. High-Density Table Styling */
#inventoryTable {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    margin-top: 1rem;
}

/* Sticky Header - Crucial for deep scanning */
#inventoryTable thead th {
    
    top: 73px; /* Sits right under the global nav */
    background: var(--surface-muted);
    z-index: 10;
    border-bottom: 2px solid var(--primary-blue);
    padding: 15px;
}

/* Zebra Striping for wide-eye scanning */
#inventoryTable tbody tr:nth-child(even) {
    background: rgba(0,0,0,0.02);
}

[data-theme="dark"] #inventoryTable tbody tr:nth-child(even) {
    background: rgba(255,255,255,0.03);
}

/* 4. Optimized Filter Bar for Wide Screens */
.inventory-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--pos-border);
}

/* Expand the search bar to utilize extra space */
.filters input[name="q"] {
    width: 400px;
    transition: width 0.3s ease;
}

.filters input[name="q"]:focus {
    width: 550px;
}

/* 5. Stock Breakdown Grid (Side-by-side locations) */
.stock-breakdown ul {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 12px;
    padding: 10px;
    background: var(--surface-muted);
    border-left: 4px solid var(--primary-blue);
    border-radius: 4px;
}



