[data-theme="dark"] .product-area { background: #0f172a; }
[data-theme="dark"] .product-card { background: #1e293b; border-color: #334155; }
[data-theme="dark"] .card-name { color: #f1f5f9; }
[data-theme="dark"] .checkout-sidebar { background: #1e293b; }
[data-theme="dark"] .billing-summary { background: #1e293b; border-top-color: #334155; }



/* Let the web cash register scroll when the checkout stack exceeds the viewport. */
body.page-cash-register {
    height: auto !important;
    min-height: 100vh;
    overflow-y: auto !important;
    overflow-x: hidden !important;
}

body.page-cash-register .pos-grid {
    min-height: calc(100vh - 75px);
    height: auto !important;
    overflow: visible !important;
