/* =====================================================
   PAGE: SUPPLIER LEDGER
===================================================== */

:root {
    --primary-blue: #3b82f6;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --pos-border: #e2e8f0;
    --pos-dark: #0f172a;
    --soft-gray: #94a3b8;
    --bg-slate: #f8fafc;
}

/* 1. Page Context */
.page-supplier-ledger {
    background: var(--bg-slate);
    padding: 2rem;
    font-family: 'Inter', sans-serif;
    margin: 0;
}

.ledger-container {
    width: 100%;
    max-width: 1600px; /* Enhanced wide view for financial density */
    margin: 0 auto;
    animation: fadeIn 0.4s ease-out;
}

/* 2. Stat Cards (Executive Summary) */
.summary-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.stat-card {
    background: white;
    padding: 25px;
    border-radius: 12px;
    border: 1px solid var(--pos-border);
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
    transition: transform 0.2s ease;
}

.stat-card:hover { transform: translateY(-3px); }

.stat-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    font-weight: 800;
    color: var(--soft-gray);
    letter-spacing: 1px;
}

.stat-value {
    font-size: 1.8rem;
    font-weight: 900;
    color: var(--pos-dark);
    margin-top: 5px;
    font-family: 'JetBrains Mono', monospace !important;
}

/* 3. Table Wrapper (Horizontal Scroll Protection) */
.table-wrapper {
    background: white;
    border-radius: 12px;
    border: 1px solid var(--pos-border);
    overflow-x: auto; /* Essential for wide financial tables */
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.05);
}

.invoice-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 1100px; /* Forces scroll instead of squishing columns */
}

.invoice-table th {
    background: #f1f5f9;
    padding: 15px 20px;
    text-align: left;
    font-size: 0.7rem;
    text-transform: uppercase;
    color: #475569;
    border-bottom: 2px solid var(--pos-border);
}

.invoice-table td {
    padding: 15px 20px;
    border-bottom: 1px solid #f1f5f9;
    font-size: 0.85rem;
    color: #334155;
}

/* 4. Financial Column Specifics */
.debit { color: var(--pos-dark); font-weight: 600; font-family: 'JetBrains Mono'; }
.credit { color: var(--success-green); font-weight: 600; font-family: 'JetBrains Mono'; }
.balance-col { 
    background: rgba(59, 130, 246, 0.03); 
    font-weight: 800; 
    color: var(--primary-blue);
    font-family: 'JetBrains Mono';
}


/* 5. Components: Buttons & Badges */
.btn-new {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--pos-dark);
    color: white !important;
    margin-top: 25px;
    padding: 10px 20px;
    border-radius: 10px;
    text-decoration: none;
    font-weight: 800;
    font-size: 0.8rem;
    transition: all 0.2s;
}


.btn-new:hover {
    background: var(--primary-blue);
    transform: translateY(-2px);
}

.status-badge {
    padding: 4px 10px;
    border-radius: 20px;
    font-size: 0.65rem;
    font-weight: 800;
    text-transform: uppercase;
    display: inline-block;
}

.status-paid { background: #dcfce7; color: #166534; }
.status-pending { background: #fef9c3; color: #854d0e; }
.status-void { background: #fee2e2; color: #991b1b; }

.pay-btn.compact {
    padding: 6px 12px;
    font-size: 0.65rem;
    border-radius: 6px;
    color: white;
    border: none;
    font-weight: 800;
    cursor: pointer;
    background: var(--primary-blue);
    transition: opacity 0.2s;
}

.pay-btn.compact:hover { opacity: 0.85; }

/* 6. Form Inputs */
.payment-form {
    display: flex;
    gap: 4px;
    background: #f8fafc;
    padding: 4px;
    border-radius: 6px;
    border: 1px solid var(--pos-border);
}

.payment-input {
    width: 85px;
    border: none;
    background: transparent;
    font-family: 'JetBrains Mono';
    font-weight: 800;
    font-size: 0.75rem;
    outline: none;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}


