/* 1. Global Page Structure */
body.settings-page {
    font-family: 'Inter', 'Segoe UI', sans-serif;
    background-color: var(--bg-canvas);
    color: var(--text-main);
    min-height: 100vh;
}

/* 2. Settings Layout Container */
.settings-container {
    max-width: 1000px;
    margin: 40px auto;
    padding: 0 20px;
    display: grid;
    grid-template-columns: 280px 1fr; /* Sidebar + Content */
    gap: 30px;
}

/* 3. Settings Sidebar Navigation */
.settings-nav {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.settings-nav-item {
    padding: 12px 16px;
    text-decoration: none;
    color: var(--text-muted);
    font-weight: 600;
    border-radius: 10px;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 12px;
}

.settings-nav-item:hover {
    background: var(--border-light);
    color: var(--dark-bg);
}

.settings-nav-item.active {
    background: var(--dark-bg);
    color: var(--white);
}

/* 4. Settings Cards (Using 'Auth-Card' Logic) */
.settings-card {
    background: var(--white);
    padding: 32px;
    border-radius: 20px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-md);
    margin-bottom: 24px;
}

.settings-card h3 {
    font-size: 1.25rem;
    font-weight: 800;
    margin-bottom: 20px;
    color: var(--dark-bg);
    border-bottom: 2px solid var(--bg-canvas);
    padding-bottom: 12px;
}

/* 5. Form Styling (Using 'Auth-Form' Logic) */
.settings-form-group {
    margin-bottom: 20px;
}

.settings-form-group label {
    display: block;
    font-weight: 700;
    font-size: 0.85rem;
    color: var(--text-main);
    margin-bottom: 8px;
}

.settings-form-group input, 
.settings-form-group select {
    width: 100%;
    padding: 12px 16px;
    border: 1.5px solid var(--border-light);
    border-radius: 10px;
    font-size: 0.95rem;
    transition: all 0.2s ease;
}

.settings-form-group input:focus {
    outline: none;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1);
}

/* 6. Action Buttons */
.btn-save {
    background: var(--primary-blue);
    color: var(--white);
    padding: 12px 24px;
    border: none;
    border-radius: 10px;
    font-weight: 700;
    cursor: pointer;
    transition: transform 0.2s ease, opacity 0.2s;
}

.btn-save:hover {
    transform: translateY(-1px);
    opacity: 0.95;
}

.btn-danger-outline {
    background: transparent;
    color: var(--danger-red);
    border: 1.5px solid var(--danger-red);
    padding: 10px 20px;
    border-radius: 10px;
    font-weight: 600;
    cursor: pointer;
}

.btn-danger-outline:hover {
    background: var(--danger-red);
    color: var(--white);
}

/* 7. Profile Header Component */
.profile-header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 30px;
}

.profile-avatar-large {
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--dark-bg), var(--dark-surface));
    color: white;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-size: 2rem;
    font-weight: 800;
    border: 4px solid var(--white);
    box-shadow: var(--shadow-md);
}

/* 8. Mobile Responsiveness */
@media (max-width: 768px) {
    .settings-container {
        grid-template-columns: 1fr;
        margin: 20px auto;
    }
    
    .settings-nav {
        flex-direction: row;
        overflow-x: auto;
        padding-bottom: 10px;
    }
    
    .settings-nav-item {
        white-space: nowrap;
    }
}

