/* =====================================================
   SALES NAV DROPDOWN + QUOTE/INVOICE PAGES
===================================================== */

#main-nav .sales-nav-item {
    position: relative;
    display: inline-flex;
    align-items: stretch;
}

#main-nav .sales-nav-trigger {
    border: 0;
    background: transparent;
    color: var(--text-muted);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: normal;
    padding: 18px 0;
    border-bottom: 3px solid transparent;
    transition: all 0.2s ease;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    font-family: inherit;
}

#main-nav .sales-nav-trigger:hover,
#main-nav .sales-nav-trigger.active,
#main-nav .sales-nav-item.is-active .sales-nav-trigger {
    color: var(--primary-blue);
    border-bottom-color: var(--primary-blue);
}

#main-nav .sales-nav-caret {
    width: 7px;
    height: 7px;
    border-right: 1.8px solid currentColor;
    border-bottom: 1.8px solid currentColor;
    transform: rotate(45deg) translateY(-1px);
    transition: transform 0.2s ease;
}

#main-nav .sales-nav-item.is-open .sales-nav-caret {
    transform: rotate(-135deg) translateY(-1px);
}

#main-nav .sales-nav-menu {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    min-width: 210px;
    display: none;
    flex-direction: column;
    border: 1px solid var(--pos-border);
    border-radius: 12px;
    background: #ffffff;
    box-shadow: 0 14px 26px rgba(15, 23, 42, 0.14);
    z-index: 1205;
    overflow: hidden;
}

#main-nav .sales-nav-item:hover .sales-nav-menu,
#main-nav .sales-nav-item.is-open .sales-nav-menu,
#main-nav .sales-nav-menu.show {
    display: flex;
}

#main-nav .sales-nav-menu a {
    padding: 11px 13px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 0;
    border-top: 0;
    border-left: 0;
    border-right: 0;
    font-size: 0.73rem;
    color: #334155;
    text-transform: uppercase;
    letter-spacing: 0.35px;
}

#main-nav .sales-nav-menu a:last-child {
    border-bottom: 0;
}

#main-nav .sales-nav-menu a:hover,
#main-nav .sales-nav-menu a.active {
    color: var(--primary-blue);
    background: #f8fbff;
}

.sales-page-main {
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px 20px 38px;
}

.sales-page-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.sales-page-title {
    margin: 0;
    font-size: 1.28rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #0f172a;
}

.sales-page-subtitle {
    margin: 4px 0 0;
    color: var(--text-muted);
    font-size: 0.84rem;
}

.sales-filter-wrap {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
    margin-bottom: 14px;
}

.sales-filter-wrap input,
.sales-filter-wrap select {
    border: 1px solid var(--pos-border);
