    letter-spacing: 0.4px;
    font-weight: 800;
    background: #f8fafc;
}

.sales-table tbody tr:last-child td {
    border-bottom: 0;
}

.sales-chip {
    display: inline-flex;
    align-items: center;
    padding: 4px 9px;
    border-radius: 999px;
    font-size: 0.68rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.45px;
}

.sales-chip.status-draft { background: #e0e7ff; color: #3730a3; }
.sales-chip.status-converted { background: #dcfce7; color: #166534; }
.sales-chip.status-cancelled { background: #fee2e2; color: #991b1b; }
.sales-chip.status-issued { background: #dbeafe; color: #1d4ed8; }
.sales-chip.status-paid { background: #dcfce7; color: #166534; }
.sales-chip.status-void { background: #fee2e2; color: #991b1b; }

.sales-detail-grid {
    display: grid;
