    align-items: center;
    gap: 10px;
    font-size: 0.82rem;
    margin-bottom: 8px;
}

.sales-summary-row strong {
    color: #0f172a;
}

.sales-summary-row:last-child {
    margin-bottom: 0;
    padding-top: 8px;
    border-top: 1px dashed #cbd5e1;
    font-size: 0.88rem;
}

.sales-payment-form {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.sales-payment-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.sales-payment-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.sales-payment-field span {
    font-size: 0.76rem;
