    border-radius: 8px;
    padding: 8px 9px;
    font-size: 0.8rem;
}

.quote-line-remove {
    border: 1px solid #fecaca;
    border-radius: 8px;
    background: #fff5f5;
    color: #b91c1c;
    font-size: 0.72rem;
    font-weight: 800;
    padding: 8px 9px;
    cursor: pointer;
}

.quote-line-add {
    align-self: flex-start;
    border: 1px solid rgba(59, 130, 246, 0.28);
    border-radius: 10px;
    background: rgba(59, 130, 246, 0.08);
    color: #1d4ed8;
    padding: 9px 12px;
    font-weight: 800;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.45px;
