/* =====================================================
   GLOBAL SEARCH SLIDE PANEL
===================================================== */
.global-search-overlay {
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.45);
    z-index: 1250;
}

.global-search-panel {
    position: fixed;
    top: 0;
    right: 0;
    height: 100vh;
    width: min(92vw, 560px);
    background: #ffffff;
    border-left: 1px solid #dbe3ef;
    box-shadow: -14px 0 34px rgba(15, 23, 42, 0.18);
    z-index: 1260;
    transform: translateX(104%);
    transition: transform 0.24s ease;
    display: flex;
    flex-direction: column;
}

.global-search-panel.is-open {
    transform: translateX(0);
}

body.global-search-open {
    overflow: hidden;
}

.global-search-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px;
    border-bottom: 1px solid #e2e8f0;
    background: #f8fafc;
}

.global-search-panel-head h3 {
    margin: 0;
    font-size: 0.88rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    color: #0f172a;
}

.global-search-close {
    border: 0;
    background: transparent;
    color: #334155;
    font-size: 1.45rem;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
    padding: 0;
}

.global-search-panel-form {
    display: grid;
    grid-template-columns: 1fr 120px auto;
    gap: 8px;
    padding: 12px 16px;
    border-bottom: 1px solid #e2e8f0;
}

.global-search-panel-form input,
.global-search-panel-form select {
    width: 100%;
    border: 1px solid #d1d9e7;
    border-radius: 8px;
    padding: 10px 11px;
    font-size: 0.82rem;
    color: #0f172a;
    background: #ffffff;
}

.global-search-panel-form button {
    border: 0;
    border-radius: 8px;
    background: var(--primary-blue);
    color: #ffffff;
    font-size: 0.8rem;
    font-weight: 800;
    letter-spacing: 0.3px;
    padding: 10px 12px;
    cursor: pointer;
}

.global-search-panel-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
    padding: 10px 16px 6px;
}

.global-search-chip {
    border: 1px solid #d7e0ee;
    border-radius: 999px;
    padding: 6px 10px;
    font-size: 0.72rem;
    font-weight: 800;
    color: #475569;
    background: #ffffff;
}

.global-search-panel-results {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 10px 16px 14px;
}

.global-search-placeholder {
    margin: 0;
    border: 1px dashed #cbd5e1;
    border-radius: 10px;
    background: #f8fafc;
    color: #334155;
    font-size: 0.8rem;
    font-weight: 600;
    padding: 12px;
}

.global-search-role-note {
    margin-bottom: 10px;
    border: 1px solid #fed7aa;
    border-radius: 8px;
    background: #fff7ed;
    color: #9a3412;
    font-size: 0.76rem;
    font-weight: 700;
    padding: 10px 11px;
}

.global-search-result-section {
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    overflow: hidden;
    background: #ffffff;
    margin-bottom: 12px;
}

.global-search-result-section h4 {
    margin: 0;
    border-bottom: 1px solid #e2e8f0;
    background: #f8fafc;
    color: #334155;
    font-size: 0.74rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    padding: 10px 12px;
}

.global-search-result-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.global-search-result-table {
    width: 100%;
    min-width: 560px;
    border-collapse: collapse;
}

.global-search-result-table th,
.global-search-result-table td {
    padding: 10px 11px;
    border-bottom: 1px solid #ecf0f5;
    text-align: left;
    vertical-align: middle;
    font-size: 0.76rem;
    color: #1e293b;
}

.global-search-result-table th {
    color: #64748b;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.4px;
    text-transform: uppercase;
}

.global-search-result-table tr:last-child td {
    border-bottom: 0;
}

.global-search-result-table td.strong {
    font-weight: 800;
}

.global-search-action {
    color: var(--primary-blue);
    text-decoration: none;
    font-weight: 800;
    font-size: 0.72rem;
}

.global-search-panel-foot {
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
    padding: 11px 16px;
}

.global-search-panel-foot a {
    color: #334155;
    text-decoration: none;
    font-weight: 700;
    font-size: 0.78rem;
}

.global-search-panel-foot a:hover {
    color: var(--primary-blue);
}

@media (max-width: 760px) {
    .global-search-panel {
        width: 100vw;
    }

    .global-search-panel-form {
        grid-template-columns: 1fr;
    }
}

