/* =====================================================
   PAGE: SETTINGS & PROFILE
   Theme: Midnight Dashboard / Professional Slate
===================================================== */

:root {
    --primary-blue: #3b82f6;
    --dark-bg: #0f172a;
    --dark-surface: #1e293b;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --bg-canvas: #f8fafc;
    --border-light: #e2e8f0;
    --white: #ffffff;
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

/* 1. Global Page Structure */
body.settings-page {
    font-family: 'Inter', 'Segoe UI', sans-serif;
    background-color: var(--bg-canvas);
    color: var(--text-main);
    min-height: 100vh;
}

/* 2. Settings Layout Container */
.settings-container {
    max-width: 1000px;
    margin: 40px auto;
    padding: 0 20px;
    display: grid;
    grid-template-columns: 280px 1fr; /* Sidebar + Content */
    gap: 30px;
}

/* 3. Settings Sidebar Navigation */
.settings-nav {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.settings-nav-item {
    padding: 12px 16px;
    text-decoration: none;
    color: var(--text-muted);
    font-weight: 600;
    border-radius: 10px;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 12px;
}

.settings-nav-item:hover {
    background: var(--border-light);
    color: var(--dark-bg);
}

.settings-nav-item.active {
    background: var(--dark-bg);
    color: var(--white);
}

/* 4. Settings Cards (Using 'Auth-Card' Logic) */
.settings-card {
    background: var(--white);
    padding: 32px;
    border-radius: 20px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-md);
    margin-bottom: 24px;
}

.settings-card h3 {
    font-size: 1.25rem;
    font-weight: 800;
    margin-bottom: 20px;
    color: var(--dark-bg);
    border-bottom: 2px solid var(--bg-canvas);
    padding-bottom: 12px;
}

/* 5. Form Styling (Using 'Auth-Form' Logic) */
.settings-form-group {
    margin-bottom: 20px;
}

.settings-form-group label {
    display: block;
    font-weight: 700;
    font-size: 0.85rem;
    color: var(--text-main);
    margin-bottom: 8px;
}

.settings-form-group input, 
.settings-form-group select {
    width: 100%;
    padding: 12px 16px;
    border: 1.5px solid var(--border-light);
    border-radius: 10px;
    font-size: 0.95rem;
    transition: all 0.2s ease;
}

.settings-form-group input:focus {
    outline: none;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1);
}

/* 6. Action Buttons */
.btn-save {
    background: var(--primary-blue);
    color: var(--white);
    padding: 12px 24px;
    border: none;
    border-radius: 10px;
    font-weight: 700;
    cursor: pointer;
    transition: transform 0.2s ease, opacity 0.2s;
}

.btn-save:hover {
    transform: translateY(-1px);
    opacity: 0.95;
}

.btn-danger-outline {
    background: transparent;
    color: var(--danger-red);
    border: 1.5px solid var(--danger-red);
    padding: 10px 20px;
    border-radius: 10px;
    font-weight: 600;
    cursor: pointer;
}

.btn-danger-outline:hover {
    background: var(--danger-red);
    color: var(--white);
}

/* 7. Profile Header Component */
.profile-header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 30px;
}

.profile-avatar-large {
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--dark-bg), var(--dark-surface));
    color: white;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-size: 2rem;
    font-weight: 800;
    border: 4px solid var(--white);
    box-shadow: var(--shadow-md);
}

/* 8. Mobile Responsiveness */
@media (max-width: 768px) {
    .settings-container {
        grid-template-columns: 1fr;
        margin: 20px auto;
    }
    
    .settings-nav {
        flex-direction: row;
        overflow-x: auto;
        padding-bottom: 10px;
    }
    
    .settings-nav-item {
        white-space: nowrap;
    }
}


/* =====================================================
   PAGE: DASHBOARD COMMAND CENTER
   Theme: Dashboard Midnight / Professional Slate
===================================================== */

:root {
    /* Core Palette */
    --primary-blue: #3b82f6;
    --dark-bg: #0f172a;
    --dark-surface: #1e293b;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --warning-orange: #f59e0b;
    
    /* Text & UI */
    --text-main: #1e293b;
    --text-muted: #64748b;
    --bg-canvas: #f8fafc;
    --border-light: #e2e8f0;
    --white: #ffffff;
    
    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

/* 1. Global Reset & Body */
* { margin: 0; padding: 0; box-sizing: border-box; }

body.page-dashboard {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg-canvas);
    color: var(--text-main);
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}


/* 2. Header: Professional Command Bar */
header {
    background: var(--dark-bg);
    color: var(--white);
    padding: 12px 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-blue);
    position: sticky;
   
    top: 0;
    z-index: 1000;
}

.logo-area {
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none;
    color: var(--white);
}

.logo-img {
    height: 32px;
    border-radius: 6px;
}

.status-pill {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid var(--success-green);
    color: var(--success-green);
    padding: 6px 12px;
    border-radius: 50px;
    font-size: 0.75rem;
    font-weight: 800;
    text-decoration: none;
    transition: all 0.2s;
}

.status-pill:hover { background: var(--success-green); color: white; }

/* 3. Navigation: Tabs-Style */
nav {
    background: var(--white);
    display: flex;
    padding: 0 30px;
    gap: 20px;
    border-bottom: 1px solid var(--border-light);
    overflow-x: auto;
    
    
}

nav a {
    padding: 15px 5px;
    text-decoration: none;
    color: var(--text-muted);
    font-size: 0.9rem;
    font-weight: 600;
    border-bottom: 3px solid transparent;
    transition: all 0.2s;
    white-space: nowrap;
}

nav a:hover { color: var(--primary-blue); }

nav a.active {
    color: var(--primary-blue);
    border-bottom-color: var(--primary-blue);
}

/* 4. Layout Container */
main {
    flex: 1;
    padding: 25px 30px;
    max-width: 1400px;
    width: 100%;
    margin: 0 auto;
}

/* 5. Welcome & Filters */
.welcome-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 25px;
    flex-wrap: wrap;
    gap: 15px;
}

.welcome-header h2 { font-weight: 800; font-size: 1.75rem; color: var(--dark-bg); letter-spacing: -0.5px; }

.filter-form {
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--white);
    padding: 8px 15px;
    border-radius: 10px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-sm);
}

.filter-form select {
    padding: 6px;
    border: 1px solid var(--border-light);
    border-radius: 6px;
    font-weight: 600;
}

.btn-apply {
    background: var(--dark-bg);
    color: grey;
    border: none;
    padding: 8px 16px;
    border-radius: 6px;
    font-weight: 700;
    cursor: pointer;
}

/* 6. KPI Grid & Cards */
.kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 18px;
}

.kpi-card {
    background: var(--white);
    padding: 24px;
    border-radius: 14px;
    border: 1px solid var(--border-light);
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s;
}

.kpi-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }

.kpi-label {
    display: block;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 8px;
}

.kpi-value {
    font-size: 2rem;
    font-weight: 800;
    color: var(--dark-bg);
    font-family: 'JetBrains Mono', monospace;
    margin-bottom: 10px;
}

/* 7. Badges & Progress */
.badge {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: 800;
}

.badge-success { background: #dcfce7; color: #166534; }

.progress-track {
    background: #e2e8f0;
    height: 8px;
    border-radius: 10px;
    margin-top: 15px;
    overflow: hidden;
}

.progress-fill {
    height: 100%;
    background: var(--primary-blue);
    border-radius: 10px;
    transition: width 1s ease-in-out;
}

/* 8. Mini Tables (Inside KPI Cards) */
.mini-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
}

.mini-table td {
    padding: 8px 0;
    border-bottom: 1px solid #f1f5f9;
}

/* 9. Activity/Log Table */
.activity-card {
    background: var(--white);
    margin-top: 25px;
    border-radius: 14px;
    border: 1px solid var(--border-light);
    padding: 20px;
}

.activity-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}

.activity-table th {
    text-align: left;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--text-muted);
    padding: 12px;
    border-bottom: 2px solid var(--border-light);
}

.activity-table td {
    padding: 12px;
    font-size: 0.85rem;
    border-bottom: 1px solid #f8fafc;
}

.severity-badge {
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 0.65rem;
    font-weight: 800;
    margin-left: 5px;
}

/* 10. Maintenance Footer Bar */
.admin-footer-bar {
    margin-top: 25px;
    background: #fff1f2;
    border: 1px solid #fecdd3;
    padding: 20px;
    border-radius: 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.btn-danger-outline {
    background: transparent;
    border: 2px solid var(--danger-red);
    color: var(--danger-red);
    padding: 10px 20px;
    border-radius: 8px;
    font-weight: 800;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-danger-outline:hover { background: var(--danger-red); color: white; }

/* 11. Global Footer */
footer {
    padding: 40px 30px;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.85rem;
}

.version-badge {
    background: var(--dark-bg);
    color: var(--primary-blue);
    padding: 4px 10px;
    border-radius: 4px;
    font-weight: 800;
    font-size: 0.7rem;
}

/* 12. Responsive */
@media (max-width: 768px) {
    .welcome-header { flex-direction: column; align-items: flex-start; }
    .kpi-grid { grid-template-columns: 1fr; }
    .activity-table th:nth-child(1), .activity-table td:nth-child(1) { display: none; }
}

/* =====================================================
   PAGE: DASHBOARD COMMAND CENTER - Mobile styles
===================================================== */
@media (max-width: 768px) {
    /* 1. Global Spacing */
    main {
        padding: 12px; /* Slightly tighter for smaller screens */
    }

    /* 2. Header & Branding */
    header {
        flex-direction: column;
        height: auto;
        padding: 15px !important;
        gap: 12px;
    }

    .logo-area {
        width: 100%;
        justify-content: center;
    }

    header > div:last-child > div:first-child {
        display: none !important;
    }

    /* 3. Navigation Bar */
    nav {
        top: 0;
        z-index: 999;
        display: flex;
        overflow-x: auto;
        white-space: nowrap;
        padding: 0 10px;
        background: var(--white);
        border-bottom: 2px solid var(--primary-blue);
        -webkit-overflow-scrolling: touch;
        gap: 8px;
    }

    nav a {
        padding: 12px 10px;
        font-size: 0.8rem;
    }

    /* 4. Performance Hub Header */
    .welcome-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
        margin-bottom: 20px;
    }

    .welcome-header h2 {
        font-size: 1.3rem;
        word-break: break-word; /* Prevents long titles from overflowing */
    }

    .filter-form {
        width: 100%;
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 8px;
    }

    /* 5. KPI Grid & Truncation - ENSURING WORDS FIT */
    .kpi-grid {
        grid-template-columns: 1fr !important;
        gap: 12px;
    }

    .kpi-card {
        padding: 18px;
        width: 100%;
        overflow: hidden;
        box-sizing: border-box;
    }

    .kpi-value {
        font-size: 1.5rem; /* Scaled down to fit currency symbols */
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .mini-table {
        table-layout: fixed; 
        width: 100%;
    }

    .mini-table td:first-child {
        width: 60%;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis; /* Keeps long product names inside */
    }

   /* 6. System Events Card Transformation - OVERFLOW FIXED */
    .activity-card {
        padding: 12px;
        width: 100% !important;
        overflow: hidden;
        box-sizing: border-box;
    }

    .activity-table, .activity-table tbody, .activity-table tr, .activity-table td {
        display: block !important;
        width: 100% !important;
        box-sizing: border-box;
    }

    .activity-table tr {
        border: 1px solid var(--border-light) !important;
        border-radius: 8px;
        padding: 12px;
        margin-bottom: 12px;
        background: var(--bg-canvas);
    }

    .activity-table td {
        padding: 4px 0 !important;
        white-space: normal !important; 
        overflow-wrap: break-word; /* Forces long SKUs/strings to wrap */
        word-wrap: break-word;
        word-break: break-word; /* Absolute fallback for long words */
        font-size: 0.8rem;
    }

    /* Label injection */
    .activity-table td:nth-child(2):before { content: "OPERATOR: "; font-weight: 800; color: var(--text-muted); font-size: 0.65rem; }
    .activity-table td:nth-child(3):before { content: "ACTION: "; font-weight: 800; color: var(--text-muted); font-size: 0.65rem; }

    /* The Log Message row - specifically handle wrapping */
    .activity-table td:last-child {
        border-top: 1px dashed var(--border-light) !important;
        margin-top: 8px;
        padding-top: 10px !important;
        color: var(--text-main);
        font-family: 'JetBrains Mono', monospace;
        line-height: 1.4;
        word-break: break-word; 
    }

    .activity-table thead, .activity-table td:first-child { 
        display: none !important; 
    }

    /* 7. Footer & Maintenance */
    .admin-footer-bar {
        flex-direction: column;
        gap: 15px;
        text-align: center;
        padding: 15px;
    }

    .btn-danger-outline {
        width: 100%;
    }
}

/* 600px Extra Refinement */
@media (max-width: 600px) {
    .kpi-value { font-size: 1.4rem; }
    .welcome-header h2 { font-size: 1.2rem; }
    
    #userMenuBtn {
        width: 100%;
        justify-content: space-between;
    }

    .kpi-card ul { 
        padding-left: 1.2rem; 
        font-size: 0.8rem;
    }
    
    .kpi-card ul li {
        margin-bottom: 8px;
        word-break: break-word; /* Fixes roadmap text spill */
    }
}


/* =====================================================
   PAGE: ADVANCED ANALYTICS
   Midnight High-Contrast / Data-Focus
===================================================== */

:root {
    /* Functional Palette */
    --primary-blue: #3b82f6;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --dark-bg: #0f172a;
    
    /* Light Mode (Default) */
    --surface: #ffffff;
    --surface-muted: #f8fafc;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --bg-canvas: #f1f5f9;
    --card-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

/* Dark Mode Overrides */
[data-theme="dark"], .force-dark {
    --surface: #1e293b;
    --surface-muted: #0f172a;
    --text-main: #f1f5f9;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --bg-canvas: #0f172a;
}

/* 1. Base Styles */
body {
    background-color: var(--bg-canvas);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    margin: 0;
    transition: background 0.3s ease, color 0.3s ease;
}

main {
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px;
}

/* 2. Header & Navigation Sync */
header {
    background: var(--dark-bg);
    padding: 12px 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid var(--primary-blue);
    top: 0;
    z-index: 1000;
}

.logo-ja {
    font-style: italic;
    background: linear-gradient(180deg, #ffffff 0%, #cbd5e1 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    padding-left: 1px;
}
.slogan {
    font-size: 0.50rem; /* Slightly smaller for better hierarchy */
    font-weight: 600;
    color: rgba(255, 255, 255, 0.85); /* Off-white for better contrast on the gradient */
    margin-top: 2px;
    padding: 2px 6px;
    background: rgba(255, 255, 255, 0.1); /* Very subtle highlight */
    border-radius: 4px;
    letter-spacing: 1.2px;
    text-transform: uppercase;
    backdrop-filter: blur(4px); /* Modern frosted glass effect */
}

/* 3. Report Cards */
.report-card {
    background: var(--surface);
    padding: 24px;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    box-shadow: var(--card-shadow);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.report-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

/* 4. Layout Grids */
.report-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 25px;
}

/* 5. Buttons & Controls */
.btn-filter {
    padding: 6px 14px;
    border-radius: 8px;
    font-size: 0.75rem;
    font-weight: 700;
    text-decoration: none;
    border: 1px solid var(--border-color);
    transition: all 0.2s;
}

.btn-filter:hover {
    border-color: var(--primary-blue);
}

.btn-export {
    display: block;
    text-align: center;
    padding: 12px;
    border-radius: 10px;
    color: white;
    text-decoration: none;
    font-weight: 700;
    font-size: 0.85rem;
    transition: filter 0.2s, transform 0.1s;
}

.btn-export:hover {
    filter: brightness(1.1);
    transform: translateY(-1px);
}

/* 6. Charts & Tables */
.chart-container {
    position: relative;
    height: 300px;
    width: 100%;
}

table th {
    border-bottom: 2px solid var(--border-color);
    padding: 10px;
}

table td {
    padding: 12px 10px;
    border-bottom: 1px solid var(--surface-muted);
}

/* 7. Restock Priority Styling */
.restock-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.restock-item {
    background: var(--surface-muted);
    padding: 12px;
    border-radius: 10px;
    border: 1px solid var(--border-color);
}

/* 8. Ledger Pulse Section */
.ledger-section {
    position: relative;
    overflow: hidden;
}

.ledger-section::after {
    content: "ANALYSIS_ACTIVE";
    position: absolute;
    top: 15px;
    right: 15px;
    font-size: 0.5rem;
    font-weight: 900;
    color: var(--primary-blue);
    opacity: 0.3;
    letter-spacing: 2px;
}



#main-nav {
    position: sticky;
    top: 70px;
    display: flex;
    justify-content: center;
    align-items: center;
    /* ... keep your existing properties ... */
}

.nav-search-link {
    position: absolute;
    right: 25px; /* Adjust to match your edge spacing */
    display: flex;
    align-items: center;
    color: var(--text-muted);
    border-bottom: none !important; /* Prevents the blue line under the icon */
    padding: 0 !important;
    transition: color 0.2s ease;
}

.nav-search-link:hover {
    color: var(--primary-blue);
}

/* Mobile Fix: Ensures the icon doesn't overlap text on small screens */
@media (max-width: 800px) {
    .nav-search-link {
        position: static;
        margin-left: 15px;
        padding: 18px 5px !important;
    }
}


/* =====================================================
   PAGE: SUPPLIER LIST
===================================================== */

:root {
    --primary-blue: #3b82f6;
    --success-green: #10b981;
    --danger-red: #ef4444;
    --pos-dark: #0f172a;
    --pos-border: #e2e8f0;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --surface: #ffffff;
    --surface-muted: #f8fafc;
}

[data-theme="dark"], .force-dark {
    --surface: #1e293b;
    --surface-muted: #0f172a;
    --text-main: #f1f5f9;
    --text-muted: #94a3b8;
    --pos-border: #334155;
    --pos-dark: #f8fafc;
}

/* 1. GLOBAL LAYOUT */
body {
    margin: 0;
    font-family: 'Inter', sans-serif;
    background-color: var(--surface-muted);
    color: var(--text-main);
}



/* 3. SUPPLIER SPECIFIC HEADER & FILTERS */
.supplier-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
}

.supplier-filters {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    gap: 15px;
    flex-wrap: wrap;
}

.supplier-filters form {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}

/* 4. TABLE COMPONENT */
.table-container {
    background: var(--surface);
    border-radius: 12px;
    border: 1px solid var(--pos-border);
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
    overflow: hidden;
}

.supplier-table {
    width: 100%;
    border-collapse: collapse;
}

.supplier-table th {
    background: var(--surface-muted);
    padding: 12px 20px;
    text-align: left;
    font-size: 0.7rem;
    text-transform: uppercase;
    color: var(--text-muted);
    border-bottom: 1px solid var(--pos-border);
}

.supplier-table td {
    padding: 15px 20px;
    border-bottom: 1px solid var(--pos-border);
    vertical-align: middle;
}

/* 5. COMPONENTS & BUTTONS */
.btn-add-supplier {
    background: var(--pos-dark);
    color: white !important;
    padding: 10px 20px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 700;
    font-size: 0.85rem;
    border: none;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    transition: opacity 0.2s;
}

.btn-add-supplier:hover {
    opacity: 0.9;
}

.badge {
    background: rgba(59, 130, 246, 0.1);
    color: var(--primary-blue);
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: 800;
}

.delete-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    transition: color 0.2s;
}

.delete-btn:hover {
    color: var(--danger-red);
}

/* 6. MOBILE STACKING LOGIC */
@media (max-width: 900px) {
    .supplier-table thead { display: none; }
    
    .supplier-table tr {
        display: block;
        padding: 15px;
        border-bottom: 4px solid var(--pos-border);
    }

    .supplier-table td {
        display: flex;
        justify-content: space-between;
        padding: 8px 0;
        border: none;
        text-align: right;
    }

    .supplier-table td::before {
        content: attr(data-label);
        font-weight: 800;
        font-size: 0.7rem;
        color: var(--text-muted);
        text-transform: uppercase;
    }

    .action-cell {
        margin-top: 10px;
        padding-top: 10px;
        border-top: 1px dashed var(--pos-border) !important;
        justify-content: flex-end;
    }
}


