}

/* 3. Table Wrapper (Horizontal Scroll Protection) */
.table-wrapper {
    background: white;
    border-radius: 12px;
    border: 1px solid var(--pos-border);
    overflow-x: auto; /* Essential for wide financial tables */
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.05);
}

.invoice-table {
