    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: flex-end;
}
body.page-audit-logs .card-header {
    padding: 20px;
    background: #f8fafc;
    border-bottom: 1px solid var(--border-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}
body.page-audit-logs .table {
    width: 100%;
