            --text-muted: #64748b;
            --bg-light: #f8fafc;
            --border-color: #e2e8f0;
            --execute-blue-bg: #eff6ff;
            --abort-red: #ef4444;
            --error-red-bg: #fee2e2;
        }
        body.page-transfer-stock { font-family: 'Inter', sans-serif; background-color: var(--bg-light); margin: 0; color: var(--text-dark); }
        body.page-transfer-stock .transfer-wrapper {
            display: grid;
            grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
            max-width: 1240px;
            margin: 26px auto 40px;
            gap: 24px;
            padding: 0 16px;
        }
        
        body.page-transfer-stock .info-panel { background: white; border-radius: 12px; padding: 30px; border: 1px solid var(--border-color); height: fit-content; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); }
        body.page-transfer-stock .qs-logo-text { font-weight: 800; font-size: 1.2rem; display: flex; align-items: center; gap: 2px; }
        body.page-transfer-stock .qs-logo-text span { color: var(--primary-blue); }
        body.page-transfer-stock .sub-header { font-size: 0.65rem; font-weight: 800; color: var(--text-dark); margin-top: 5px; letter-spacing: 1px; }
        body.page-transfer-stock .station-tag { background: #000; color: #fff; font-family: 'JetBrains Mono'; font-size: 0.6rem; padding: 2px 6px; border-radius: 4px; display: inline-block; margin-top: 10px; }
        body.page-transfer-stock .logic-title { font-size: 1.8rem; font-weight: 800; margin: 30px 0; color: var(--text-dark); }
        
        body.page-transfer-stock .preview-box { margin: 25px 0; padding: 15px; background: var(--bg-light); border-radius: 8px; border: 1px dashed #cbd5e1; }
        body.page-transfer-stock .preview-item { display: flex; justify-content: space-between; margin-bottom: 8px; font-family: 'JetBrains Mono'; font-size: 0.8rem; }
        body.page-transfer-stock .preview-qty { color: var(--primary-blue); font-weight: 800; }

        body.page-transfer-stock .form-card { background: white; border-radius: 12px; padding: 32px; border: 1px solid var(--border-color); box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); }
        body.page-transfer-stock .label-caps { display: block; font-weight: 800; font-size: 0.65rem; color: var(--text-muted); margin-bottom: 8px; letter-spacing: 0.5px; }
        body.page-transfer-stock select,
body.page-transfer-stock input { 
            width: 100%; padding: 12px 15px; border-radius: 8px; border: 1px solid var(--border-color); 
            background: #fff; font-family: 'Inter'; font-weight: 600; font-size: 0.9rem; margin-bottom: 20px;
        }

