            outline: none;
            border-color: var(--primary-blue);
            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
        }

        body.page-transfer-stock .input-error { border-color: var(--abort-red) !important; background-color: var(--error-red-bg) !important; color: var(--abort-red); }
        body.page-transfer-stock .error-msg { color: var(--abort-red); font-size: 0.7rem; font-weight: 800; margin-top: -15px; margin-bottom: 15px; display: none; }

        body.page-transfer-stock .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
        
        body.page-transfer-stock .btn-execute { 
            background: #ecfdf5; color: #059669; border: 2px solid #10b981; 
            padding: 14px 28px; border-radius: 8px; font-weight: 800; font-size: 0.8rem; 
            cursor: pointer; text-transform: uppercase; transition: all 0.2s;
        }
        body.page-transfer-stock .btn-execute:hover:not(:disabled) { background: #10b981; color: white; }
        body.page-transfer-stock .btn-execute:disabled { opacity: 0.4; cursor: not-allowed; border-color: var(--text-muted); color: var(--text-muted); }
        
        body.page-transfer-stock .btn-abort {
            background: #ffffff;
            color: #334155;
            border: 1px solid rgba(203, 213, 225, 0.95);
            padding: 14px 22px;
            border-radius: 14px;
            font-weight: 800;
            font-size: 0.95rem;
            line-height: 1;
            text-decoration: none;
            margin-left: 0;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
            transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
        }

        body.page-transfer-stock .btn-abort:hover {
            background: #f8fafc;
            border-color: rgba(148, 163, 184, 0.95);
            color: #0f172a;
            transform: translateY(-1px);
        }

        @media (max-width: 980px) {
body.page-transfer-stock .transfer-wrapper {
                grid-template-columns: 1fr;
                margin: 18px auto 28px;
                gap: 16px;
                padding: 0 12px;
            }

