                justify-content: center !important;
                gap: 10px;
            }

            body.page-transfer-stock .transfer-actions .btn-execute,
body.page-transfer-stock .transfer-actions .btn-abort {
                width: min(100%, 260px);
                text-align: center;
                margin-left: 0;
                margin-right: 0;
                align-self: center;
            }

            body.page-transfer-stock select,
body.page-transfer-stock input {
                font-size: 16px;
            }
}

