.qs-error-overlay[hidden] {
    display: none !important;
}

.qs-error-overlay {
    position: fixed;
    inset: 0;
    z-index: 25000;
    display: grid;
    place-items: center;
    padding: 24px;
}

.qs-error-overlay__backdrop {
    position: absolute;
    inset: 0;
    background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.16), transparent 38%),
        rgba(3, 7, 18, 0.74);
    backdrop-filter: blur(8px);
}

.qs-error-overlay__dialog {
    position: relative;
    width: min(100%, 540px);
    border-radius: 24px;
    padding: 28px;
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.92));
    color: #e2e8f0;
    border: 1px solid rgba(148, 163, 184, 0.28);
    box-shadow: 0 28px 80px rgba(2, 6, 23, 0.45);
}

.qs-error-overlay__eyebrow {
    margin: 0 0 10px;
    color: #38bdf8;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.qs-error-overlay__title {
    margin: 0;
    font-size: clamp(1.45rem, 1.2rem + 0.8vw, 2rem);
    line-height: 1.1;
    color: #f8fafc;
}

.qs-error-overlay__message {
    margin: 14px 0 0;
    color: rgba(226, 232, 240, 0.88);
    font-size: 0.98rem;
    line-height: 1.6;
}

.qs-error-overlay__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 22px;
}

.qs-error-overlay__button {
    appearance: none;
    border: 1px solid rgba(148, 163, 184, 0.34);
    background: rgba(15, 23, 42, 0.74);
    color: #e2e8f0;
    border-radius: 999px;
    padding: 11px 18px;
    font-weight: 700;
    cursor: pointer;
    transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}

.qs-error-overlay__button:hover {
    transform: translateY(-1px);
    background: rgba(30, 41, 59, 0.92);
    border-color: rgba(125, 211, 252, 0.4);
}

.qs-error-overlay__button--primary {
    background: linear-gradient(135deg, #0ea5e9, #2563eb);
    border-color: transparent;
    color: #eff6ff;
}

@media (max-width: 640px) {
    .qs-error-overlay {
        padding: 16px;
    }

    .qs-error-overlay__dialog {
        border-radius: 20px;
        padding: 22px 18px;
    }

    .qs-error-overlay__actions {
        flex-direction: column;
    }

    .qs-error-overlay__button {
        width: 100%;
        justify-content: center;
    }
}

@media (max-width: 900px) {
    body.page-sales-invoice-list.page-supplier-list > header.app-shell-header {
        flex: 0 0 auto !important;
    }

    body.page-sales-invoice-list.page-supplier-list .sales-page-main.ops-shell {
        margin-top: 0 !important;
        padding-top: 5px !important;
    }
}

/* =====================================================
   Supplier origin registration + directory refinement
===================================================== */
body.page-add-supplier.page-supplier-network {
    display: block;
    min-height: 100vh;
    padding: 0;
    margin: 0;
    background:
        radial-gradient(circle at 8% 12%, rgba(16, 185, 129, 0.11), transparent 29rem),
        linear-gradient(180deg, #f8fafc 0%, #eef4f3 100%);
    background-size: auto;
    color: #0f172a;
    font-family: 'Inter', sans-serif;
}

.supplier-registration-shell {
    width: min(1180px, calc(100% - 40px));
    margin: 34px auto 60px;
}

.supplier-origin-hero {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(340px, 0.75fr);
    gap: 36px;
    align-items: center;
    padding: clamp(28px, 4vw, 48px);
    overflow: hidden;
    border: 1px solid rgba(16, 185, 129, 0.22);
    border-radius: 26px 26px 8px 26px;
    background:
        linear-gradient(112deg, rgba(6, 78, 59, 0.98), rgba(15, 118, 110, 0.94)),
        #065f46;
    box-shadow: 0 22px 48px rgba(6, 78, 59, 0.18);
    color: #ecfdf5;
}

.supplier-origin-kicker {
    margin: 0 0 12px;
    color: #a7f3d0;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

.supplier-origin-hero h1 {
    max-width: 720px;
    margin: 0;
    color: #ffffff;
    font-size: clamp(2rem, 4vw, 3.35rem);
    line-height: 1.02;
    letter-spacing: -0.045em;
}

.supplier-origin-hero-copy > p:last-child {
    max-width: 690px;
    margin: 18px 0 0;
    color: rgba(236, 253, 245, 0.82);
    font-size: 0.98rem;
    line-height: 1.7;
}

.supplier-origin-routing {
    display: grid;
    gap: 14px;
    padding: 22px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 20px 20px 6px 20px;
    background: rgba(2, 44, 34, 0.44);
}

.supplier-routing-step {
    display: flex;
    align-items: center;
    gap: 13px;
}

.supplier-routing-marker {
    display: grid;
    flex: 0 0 38px;
    width: 38px;
    height: 38px;
    place-items: center;
    border: 1px solid rgba(167, 243, 208, 0.45);
    border-radius: 10px 10px 3px 10px;
    background: rgba(167, 243, 208, 0.12);
    color: #d1fae5;
    font-size: 0.76rem;
    font-weight: 800;
}

.supplier-routing-step-international .supplier-routing-marker {
    border-color: rgba(165, 180, 252, 0.5);
    background: rgba(99, 102, 241, 0.2);
    color: #e0e7ff;
}

.supplier-routing-step strong,
.supplier-routing-step small {
    display: block;
}

.supplier-routing-step strong {
    color: #ffffff;
    font-size: 0.86rem;
}

.supplier-routing-step small {
    margin-top: 4px;
    color: rgba(236, 253, 245, 0.72);
    font-size: 0.72rem;
    line-height: 1.4;
}

.supplier-routing-divider {
    width: 1px;
    height: 12px;
    margin-left: 19px;
    background: rgba(255, 255, 255, 0.24);
}

.supplier-registration-form {
    display: grid;
    gap: 18px;
    margin-top: 22px;
}

.supplier-form-section {
    display: grid;
    grid-template-columns: minmax(220px, 0.38fr) minmax(0, 1fr);
    gap: clamp(24px, 4vw, 54px);
    padding: clamp(24px, 3.2vw, 38px);
    border: 1px solid #dce6e3;
    border-radius: 8px 24px 24px 24px;
    background: rgba(255, 255, 255, 0.94);
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.055);
}

.supplier-form-section-origin {
    border-color: rgba(16, 185, 129, 0.3);
}

.supplier-section-heading {
    display: flex;
    align-items: flex-start;
    gap: 13px;
}

.supplier-section-index {
    display: grid;
    flex: 0 0 34px;
    width: 34px;
    height: 34px;
    place-items: center;
    border-radius: 8px 8px 2px 8px;
    background: #e8f7f1;
    color: #047857;
    font-size: 0.68rem;
    font-weight: 800;
}

.supplier-section-heading h2 {
    margin: 2px 0 0;
    color: #0f172a;
    font-size: 1.02rem;
    line-height: 1.3;
}

.supplier-section-heading p {
    margin: 8px 0 0;
    color: #64748b;
    font-size: 0.78rem;
    line-height: 1.55;
}

.supplier-type-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.supplier-type-card {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 24px;
    gap: 14px;
    align-items: center;
    min-height: 126px;
    padding: 20px;
    border: 1px solid #cbd5e1;
    border-radius: 16px 16px 5px 16px;
    background: #f8fafc;
    cursor: pointer;
    transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease, background 180ms ease;
}

.supplier-type-card:hover {
    transform: translateY(-2px);
    border-color: #94a3b8;
    box-shadow: 0 12px 26px rgba(15, 23, 42, 0.08);
}

.supplier-type-card:has(input:focus-visible) {
    outline: 3px solid rgba(14, 165, 233, 0.25);
    outline-offset: 3px;
}

.supplier-type-card-local:has(input:checked) {
    border-color: #10b981;
    background: #ecfdf5;
    box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.12);
}

.supplier-type-card-international:has(input:checked) {
    border-color: #6366f1;
    background: #eef2ff;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.12);
}

.supplier-type-input {
    position: absolute;
    width: 1px !important;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

.supplier-type-card-title,
.supplier-type-card-copy {
    display: block;
}

.supplier-type-card-title {
    color: #0f172a;
    font-size: 0.92rem;
    font-weight: 800;
}

.supplier-type-card-copy {
    margin-top: 8px;
    color: #64748b;
    font-size: 0.76rem;
    line-height: 1.55;
}

.supplier-type-check {
    position: relative;
    width: 20px;
    height: 20px;
    border: 2px solid #94a3b8;
    border-radius: 50%;
    background: #ffffff;
}

.supplier-type-card:has(input:checked) .supplier-type-check::after {
    content: "";
    position: absolute;
    inset: 4px;
    border-radius: inherit;
    background: #10b981;
}

.supplier-type-card-international:has(input:checked) .supplier-type-check::after {
    background: #6366f1;
}

.supplier-field-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
}

.supplier-field-wide {
    grid-column: 1 / -1;
}

.supplier-field label {
    display: block;
    margin-bottom: 8px;
    color: #475569;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.035em;
    text-transform: uppercase;
}

.page-add-supplier .supplier-field input,
.page-add-supplier .supplier-field select,
.page-add-supplier .supplier-field textarea {
    width: 100%;
    min-height: 48px;
    box-sizing: border-box;
    padding: 12px 14px;
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    outline: none;
    background: #ffffff;
    color: #0f172a;
    font: inherit;
    font-size: 0.88rem;
    transition: border-color 180ms ease, box-shadow 180ms ease;
}

.page-add-supplier .supplier-field textarea {
    min-height: 112px;
    resize: vertical;
}

.page-add-supplier .supplier-field input:focus,
.page-add-supplier .supplier-field select:focus,
.page-add-supplier .supplier-field textarea:focus {
    border-color: #0f9f76;
    box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.12);
}

.supplier-form-error {
    margin-top: 7px;
    color: #b91c1c;
    font-size: 0.74rem;
    font-weight: 700;
}

.supplier-form-error ul {
    margin: 0;
    padding-left: 18px;
}

.supplier-form-error-summary,
.supplier-form-messages {
    padding: 14px 18px;
    border: 1px solid rgba(220, 38, 38, 0.24);
    border-radius: 10px;
    background: #fef2f2;
}

.supplier-form-messages {
    margin-bottom: 18px;
    border-color: rgba(16, 185, 129, 0.28);
    background: #ecfdf5;
    color: #065f46;
    font-size: 0.82rem;
    font-weight: 700;
}

.supplier-form-messages p {
    margin: 0;
}

.supplier-form-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding: 24px 28px;
    border: 1px solid #dce6e3;
    border-radius: 18px 18px 6px 18px;
    background: #ffffff;
}

.supplier-form-actions > p {
    max-width: 610px;
    margin: 0;
    color: #64748b;
    font-size: 0.78rem;
    line-height: 1.55;
}

.supplier-form-actions > p strong {
    color: #0f766e;
}

.supplier-form-actions > div {
    display: flex;
    gap: 10px;
}

.supplier-action {
    display: inline-flex;
    min-height: 46px;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    padding: 0 22px;
    border: 1px solid transparent;
    border-radius: 10px;
    font: inherit;
    font-size: 0.78rem;
    font-weight: 800;
    text-decoration: none;
    cursor: pointer;
    transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.supplier-action:hover {
    transform: translateY(-1px);
}

.supplier-action-secondary {
    border-color: #cbd5e1;
    background: #ffffff;
    color: #475569;
}

.supplier-action-primary {
    background: #047857;
    color: #ffffff;
    box-shadow: 0 10px 20px rgba(4, 120, 87, 0.2);
}

.supplier-action-primary:hover,
.supplier-action-primary:focus-visible {
    background: #065f46;
}

