/* =====================================================
   QUICKSTOCK JA - LOADING STATE SYSTEM
===================================================== */
.qs-page-progress {
    position: fixed;
    top: 0;
    left: 0;
    z-index: 3000;
    width: 100%;
    height: 3px;
    pointer-events: none;
    opacity: 0;
    transform: translateY(-3px);
    transition: opacity 140ms ease, transform 140ms ease;
}

.qs-page-progress.is-visible {
    opacity: 1;
    transform: translateY(0);
}

.qs-page-progress-fill {
    display: block;
    width: 0;
    height: 100%;
    border-radius: 0 999px 999px 0;
    background: linear-gradient(90deg, var(--primary-blue, #0b72d9), var(--success-green, #2ed573));
    box-shadow: 0 0 14px rgba(11, 114, 217, 0.38);
    transition: width 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

.qs-button-loading {
    position: relative;
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 8px;
    cursor: wait !important;
}

.qs-button-loading[disabled],
.qs-button-loading:disabled {
    opacity: 0.82;
}

.qs-button-loading:focus-visible {
    outline: 3px solid rgba(11, 114, 217, 0.32);
    outline-offset: 2px;
}

.qs-button-spinner {
    width: 1em;
    height: 1em;
    flex: 0 0 auto;
    border: 2px solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: qs-spin 680ms linear infinite;
}

.qs-button-loading-label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.qs-skeleton {
    position: relative;
    overflow: hidden;
    color: transparent !important;
    border-color: transparent !important;
    background: #e5edf6 !important;
}

.qs-skeleton::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.72), transparent);
    animation: qs-shimmer 1.15s ease-in-out infinite;
}

html.force-dark .qs-skeleton,
html[data-theme-applied="dark"] .qs-skeleton {
    background: #253247 !important;
}

.pos-checkout-busy .payment-channel-panel,
.pos-checkout-busy .billing-summary {
    position: relative;
}

.pos-checkout-busy .btn-pay {
    box-shadow: 0 0 0 3px rgba(11, 114, 217, 0.16);
}

.pos-checkout-busy .payment-channel-panel::after {
    content: "";
    position: absolute;
    left: 20px;
    right: 20px;
    bottom: 0;
    height: 3px;
    border-radius: 999px;
    background: linear-gradient(90deg, var(--primary-blue, #0b72d9), var(--success-green, #2ed573), var(--primary-blue, #0b72d9));
    background-size: 180% 100%;
    animation: qs-progress-sweep 1s linear infinite;
}

@keyframes qs-spin {
    to {
        transform: rotate(360deg);
    }
}

@keyframes qs-shimmer {
    100% {
        transform: translateX(100%);
    }
}

@keyframes qs-progress-sweep {
    100% {
        background-position: 180% 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .qs-page-progress,
    .qs-page-progress-fill {
        transition: none;
    }

    .qs-button-spinner,
    .qs-skeleton::after,
    .pos-checkout-busy .payment-channel-panel::after {
        animation: none;
    }

    .qs-button-spinner {
        border-right-color: currentColor;
        opacity: 0.68;
    }

    .pos-checkout-busy .btn-pay {
        box-shadow: none;
    }
}

